// P01-UPPER-033: hold the real frame READY reply; do not forge a request/ACK
// or change service deadlines, native capabilities, focus CSS or domain state.
for (const mode of ['light', 'dark', 'high-contrast'] as const) for (const density of ['compact', 'comfortable'] as const) {
  // eslint-disable-next-line no-empty-pattern
  test('P01-UPPER-033 actual pending prepare focus lease ' + mode + ' ' + density, async ({}, info) => {
    test.setTimeout(120000)
    const f = await diagramFixture('frame', { mode, density }, page => page.setViewportSize({ width: 1280, height: 850 }))
    const observations: unknown[] = []
    try {
      const frame = f.page.frameLocator('iframe'), targets = await upperTargets(f)
      await upperPinIdentity(f, targets)
      const locate = (key: string) => frame.locator('.geToolbarContainer .geToolbar a.geButton').nth(targets.find(t => t.key === key)!.index)
      const before = { semantics: await fuiSemantics(f, 'frame'), files: await fuiFiles(f), identity: await upperCheckIdentity(f) }
      await f.page.evaluate(() => {
        const frame = document.querySelector('iframe')!
        const gate = { armed: false, held: undefined as undefined | { data: string; at: number; context: any } }
        const listener = (event: MessageEvent) => {
          if (!gate.armed || gate.held || event.source !== frame.contentWindow || event.origin !== 'frade://drawio' || typeof event.data !== 'string') return
          let data: any
          try { data = JSON.parse(event.data) } catch { return }
          if (data?.event === 'fradePresentation' && data.operation === 'prepare' && data.status === 'READY') {
            gate.held = { data: event.data, at: performance.now(), context: data.context }
            event.stopImmediatePropagation()
          }
        }
        window.addEventListener('message', listener, true)
        ;(window as any).__p01PendingFocusGate = { gate, dispose: () => window.removeEventListener('message', listener, true) }
      })
      await frame.locator('body').evaluate(() => {
        const records: any[] = []
        const listener = (event: MessageEvent) => {
          if (event.source !== parent || event.origin !== 'frade://app' || typeof event.data !== 'string') return
          let data: any
          try { data = JSON.parse(event.data) } catch { return }
          if (data?.action !== 'fradePresentation' || data.operation !== 'prepare') return
          const record = { context: data.context, before: document.documentElement.outerHTML, after: '', pure: false }
          records.push(record)
          queueMicrotask(() => { record.after = document.documentElement.outerHTML; record.pure = record.before === record.after })
        }
        window.addEventListener('message', listener, true)
        ;(window as any).__p01PendingFocusCapture = { records, dispose: () => window.removeEventListener('message', listener, true) }
      })
      for (const invalidation of ['blur', 'handoff'] as const) {
        await f.page.keyboard.press('Tab'); await locate('viewPanels').focus()
        await expect(frame.locator('body>[data-frade-upper-focus-ring]')).toHaveCount(1)
        const revision = await frame.locator('html').getAttribute('data-frade-frame-revision')
        await frame.locator('body').evaluate(() => { (window as any).__p01PendingFocusCapture.records.length = 0 })
        await f.page.evaluate(() => { const { gate } = (window as any).__p01PendingFocusGate; gate.held = undefined; gate.armed = true })
        await f.page.emulateMedia({ forcedColors: invalidation === 'blur' ? 'active' : 'none' })
        await expect.poll(() => f.page.evaluate(() => !!(window as any).__p01PendingFocusGate.gate.held)).toBe(true)
        const retained = await frame.locator('body').evaluate(() => ({
          revision: document.documentElement.getAttribute('data-frade-frame-revision'),
          ring: !!document.querySelector('body>[data-frade-upper-focus-ring]'),
          focused: document.hasFocus(), anchor: (document.activeElement as HTMLElement)?.getAttribute('aria-label'),
          records: (window as any).__p01PendingFocusCapture.records,
        }))
        expect(retained.revision).toBe(revision); expect(retained.focused).toBe(true); expect(retained.ring).toBe(true)
        expect(retained.records).toHaveLength(1); expect(retained.records[0].pure).toBe(true)
        if (invalidation === 'blur') await locate('viewPanels').evaluate(node => (node as HTMLElement).blur())
        else await locate('insert').focus()
        const invalidated = await frame.locator('body').evaluate(async () => {
          await new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve())))
          return { ring: !!document.querySelector('body>[data-frade-upper-focus-ring]'), revision: document.documentElement.getAttribute('data-frade-frame-revision'), focused: document.hasFocus() }
        })
        observations.push({ mode, density, invalidation, retained, invalidated })
        expect(invalidated.revision).toBe(revision); expect(invalidated.ring).toBe(false)
        await locate('viewPanels').focus()
        const stale = await frame.locator('body').evaluate(async () => {
          await new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve())))
          return !!document.querySelector('body>[data-frade-upper-focus-ring]')
        })
        expect(stale).toBe(false)
        const held = await f.page.evaluate(() => { const { gate } = (window as any).__p01PendingFocusGate; gate.armed = false; return gate.held })
        // Deliver exactly the captured original reply from its original source.
        await frame.locator('body').evaluate((_body, data: string) => parent.postMessage(data, 'frade://app'), held.data)
        await expect.poll(() => frame.locator('html').getAttribute('data-frade-frame-revision')).not.toBe(revision)
        await expect(f.page.locator('.frade-theme-commit-barrier')).toBeHidden()
        await locate('viewPanels').focus()
        await expect(frame.locator('body>[data-frade-upper-focus-ring]')).toHaveCount(1)
        expect(await fuiSemantics(f, 'frame')).toEqual(before.semantics)
        expect(await fuiFiles(f)).toEqual(before.files); expect(await upperCheckIdentity(f)).toEqual(before.identity)
        await f.page.screenshot({ path: info.outputPath(invalidation + '-restored-focus.png') })
      }
      await frame.locator('body').evaluate(() => { const capture = (window as any).__p01PendingFocusCapture; capture.dispose(); delete (window as any).__p01PendingFocusCapture })
      await f.page.evaluate(() => { (window as any).__p01PendingFocusGate.dispose(); delete (window as any).__p01PendingFocusGate })
    } finally {
      await writeFile(info.outputPath('pending-focus-observations.json'), JSON.stringify({ observations, visualApproval: 'NOT_APPROVED', fixture: 'Hold and deliver original READY bytes; no synthetic requests, native-state forcing or timeout changes' }, null, 2))
      await finishDiagramFixture(f.app)
    }
  })
}
